window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6e4c317f85f67896"]={"versions": [{"id": "FIG-6e4c317f85f67896", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR VFB- / UML-Komponentendiagramm mit nativer AUTOSAR Port-Interface-Notation (Ball-and-Socket / Provided- &amp; Required-Ports, Assembly-Konnektoren).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der Port-basierten BSW-Service-Schnittstellen zwischen dem <em>Basic Software Mode Manager</em> (<code>BswM</code>) und dem <em>Communication Manager</em> (<code>ComM</code>) auf RTE-/VFB-Ebene.\n</li><li><strong>Funktionale Einordnung:</strong> Der <code>BswM</code> agiert als übergeordnete Entscheidungsinstanz (Mode Manager / Rule Engine), die systemweite Betriebsmodi bewertet. Der <code>ComM</code> fungiert als ausführender Kommunikationsdienstleister (Service Component). Über die dargestellten Schnittstellen erzwingt der <code>BswM</code> restriktive Energiespar- und Bordnetzschutz-Vorgaben:\n<ul class=\"fig-list\"><li><strong>Modus-Limitierung</strong> (<em>Mode Limitation</em>): Erzwingen des Zustands <code>COMM_NO_COMMUNICATION</code> auf Kanal- oder ECU-Ebene.\n</li><li><strong>Weck-Inhibition</strong> (<em>Wakeup Inhibition</em>): Unterbindung des aktiven Aufweckens des Bussystems durch das Steuergerät.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Rollen</h5>\n<ul class=\"fig-list\"><li><strong>Basic Software Mode Manager (<code>BswM</code>):</strong> Client-Komponente; besitzt Required Ports (Schnittstellen-Buchsen) zur Ausführung konfigurierter Mode-Arbitrierungsregeln.\n</li><li><strong>Com Manager (<code>ComM</code>):</strong> Server-Komponente (<code>Service Component</code>); stellt Provided Ports (Schnittstellen-Stecker) für Mode-Management-Dienste bereit.\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; Ports</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Schnittstelle (Client-Server, <code>IsService = true</code>)</th><th>Port-Muster (ComM P-Port)</th><th>BswM R-Port</th><th>Kardinalität</th><th>Relevante Operationen &amp; Parameter</th></tr></thead><tbody><tr><td><strong><code>ComM_ChannelWakeup</code></strong>&lt;br&gt;<em>(Aktiv bei <code>ComMWakeupInhibitionEnabled == true</code>)</em></td><td><code>CW000</code>, <code>CW001</code>, …&lt;br&gt;<em>(Präfix <code>CW_{channel_name}</code>)</em></td><td>R-Port</td><td>1 … n&lt;br&gt;<em>(1 Port pro <code>ComMChannel</code>)</em></td><td>• <code>PreventWakeUp(IN boolean Status)</code>&lt;br&gt;• <code>GetInhibitionStatus(OUT ComM_InhibitionStatusType* Status)</code></td></tr><tr><td><strong><code>ComM_ChannelLimitation</code></strong>&lt;br&gt;<em>(Aktiv bei <code>ComMModeLimitationEnabled == true</code>)</em></td><td><code>CL000</code>, <code>CL001</code>, …&lt;br&gt;<em>(Präfix <code>CL_{channel_name}</code>)</em></td><td>R-Port</td><td>1 … n&lt;br&gt;<em>(1 Port pro <code>ComMChannel</code>)</em></td><td>• <code>LimitChannelToNoComMode(IN boolean Status)</code>&lt;br&gt;• <code>GetInhibitionStatus(OUT ComM_InhibitionStatusType* Status)</code></td></tr><tr><td><strong><code>ComM_ECUModeLimitation</code></strong>&lt;br&gt;<em>(Aktiv bei <code>ComMModeLimitationEnabled == true</code>)</em></td><td><code>modeLimitation</code></td><td>R-Port</td><td>1&lt;br&gt;<em>(ECU-global)</em></td><td>• <code>LimitECUToNoComMode(IN boolean Status)</code>&lt;br&gt;• <code>ReadInhibitCounter(OUT uint16* CounterValue)</code>&lt;br&gt;• <code>ResetInhibitCounter()</code>&lt;br&gt;• <code>SetECUGroupClassification(IN ComM_InhibitionStatusType Status)</code></td></tr></tbody></table></div>\n<h5 class=\"fig-section-h5\">Formalismen &amp; Port Defined Argument Values</h5>\n<ul class=\"fig-list\"><li><strong>Port Defined Arguments:</strong> Die kanalspezifischen Ports (<code>CWxxx</code>, <code>CLxxx</code>) sind im RTE-Vertrag mit einem <em>Port Defined Argument Value</em> vom Typ <code>NetworkHandleType</code> versehen (<code>ComMChannelId</code>). Dadurch mappt die RTE den parameterlosen bzw. kanallosen Portaufruf des BswM direkt auf die zugrunde liegende C-API mit dem Kanalparameter (z. B. <code>ComM_PreventWakeUp(Channel, Status)</code> bzw. <code>ComM_LimitChannelToNoComMode(Channel, Status)</code>).\n</li><li><strong>Verbindungen:</strong> 1:1 Assembly Connectors (gestrichelte Verbindungslinien) zwischen BswM-R-Ports und ComM-P-Ports.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger &amp; Regel-Evaluation (BswM):</strong>\n<ul class=\"fig-list\"><li>Ein Zustandswechsel im BswM (z. B. Transition von <em>Run</em> nach <em>PostRun</em>, Unterspannungserkennung oder Diagnoseanforderung) feuert eine Regel.\n</li><li>Der BswM führt eine zugehörige <code>BswMAction</code> aus (z. B. <code>BswMComMChannelLimitation</code>, <code>BswMComMEcuModeLimitation</code> oder <code>BswMComMPreventWakeup</code>).\n</li></ul>\n</li><li><strong>Synchroner Client-Server-Aufruf (RTE):</strong>\n<ul class=\"fig-list\"><li>Der BswM ruft synchron die Operation auf (z. B. <code>Rte_Call_CL000_LimitChannelToNoComMode(TRUE)</code>).\n</li><li>Der Aufruf blockiert den BswM-Task-Kontext nur für die Dauer der lokalen Statusaktualisierung im <code>ComM</code>.\n</li></ul>\n</li><li><strong>Zustands- und Bitvektor-Aktualisierung im ComM:</strong>\n<ul class=\"fig-list\"><li>Der ComM aktualisiert seinen internen Statusbitvektor <code>ComM_InhibitionStatusType</code>:\n<ul class=\"fig-list\"><li>Bit 0 (<code>0x01</code>): <code>Wakeup Inhibition Active</code>\n</li><li>Bit 1 (<code>0x02</code>): <code>Limited To No Com</code>\n</li></ul>\n</li></ul>\n</li><li><strong>Auswirkung auf nachfolgende Modusanforderungen:</strong>\n<ul class=\"fig-list\"><li>Geht eine Anforderung von SW-Cs über <code>ComM_RequestComMode(User, COMM_FULL_COMMUNICATION)</code> ein:\n<ul class=\"fig-list\"><li><strong>Modus-Limitierung aktiv:</strong> Die Anfrage wird synchron mit dem Fehlerwert <code>COMM_E_MODE_LIMITATION</code> abgewiesen. Der interne Inhibit-Zähler (<code>InhibitCounter</code>) wird inkrementiert (und optional im NvM persistiert).\n</li><li><strong>Weck-Inhibition aktiv:</strong> Das Steuergerät darf bei externem Weckruf teilnehmen, initiiert jedoch bei internen Kommunikationswünschen kein aktives Aufwecken der Transceiver bzw. des Busses (<code>COMM_NO_WAKEUP</code>).\n</li></ul>\n</li></ul>\n</li><li><strong>Rückmeldung &amp; Indikation:</strong>\n<ul class=\"fig-list\"><li>Der BswM kann den aktuellen Status über <code>GetInhibitionStatus()</code> synchron abfragen.\n</li><li>Kanalzustandsänderungen, die sich aus der Limitierung ergeben (Übergang in <code>COMM_NO_COMMUNICATION</code>), meldet der ComM asynchron über <code>BswM_ComM_CurrentModeIndication()</code> an den BswM zurück.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Generierung &amp; Variantenkonfiguration:</strong>\n<ul class=\"fig-list\"><li>Fehlt in der EcuC-Konfiguration <code>ComMWakeupInhibitionEnabled = TRUE</code>, werden die Ports <code>CWxxx</code> und das Interface <code>ComM_ChannelWakeup</code> vom RTE-Generator nicht erzeugt (<code>[SWS_ComM_00742]</code>, <code>[SWS_ComM_01008]</code>).\n</li><li>Fehlt <code>ComMModeLimitationEnabled = TRUE</code>, entfallen die Ports <code>CLxxx</code>, <code>modeLimitation</code> sowie die zugehörigen Interfaces (<code>[SWS_ComM_00741]</code>, <code>[SWS_ComM_00743]</code>).\n</li></ul>\n</li><li><strong>BswM-Aktionskonfiguration:</strong>\n<ul class=\"fig-list\"><li>Im BswM-Modul müssen die Aktionen exakt auf die generierten R-Ports gemappt werden. Ein typischer Konfigurationsfehler ist das Setzen von <code>ComM_LimitECUToNoComMode</code> bei gleichzeitigem Erwarten von Restkommunikation auf Teilnetzwerken (PNCs) – die ECU-Limitierung überschreibt alle lokalen Kanal- und PNC-Freigaben.\n</li></ul>\n</li><li><strong>Fehlercodes &amp; Det:</strong>\n<ul class=\"fig-list\"><li>Aufrufe vor <code>ComM_Init()</code> liefern <code>E_NOT_OK</code> und erzeugen den Det-Fehler <code>COMM_E_UNINIT</code>.\n</li><li>Ein ungültiger Index in <code>NetworkHandleType</code> erzeugt <code>COMM_E_WRONG_PARAMETERS</code>.\n</li></ul>\n</li><li><strong>NvM-Kopplung:</strong>\n<ul class=\"fig-list\"><li>Ist <code>ComMGlobalNvMBlockDescriptor</code> konfiguriert, muss zur Erfassung abgewiesener Vollkommunikations-Anfragen der Inhibit-Counter über <code>ReadInhibitCounter()</code> / <code>ResetInhibitCounter()</code> im Fehlerspeicher- oder Shutdown-Pfad berücksichtigt werden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-36028b3d7dedc2ba", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR VFB- / UML-Komponentendiagramm mit nativer AUTOSAR Port-Interface-Notation (Ball-and-Socket / Provided- &amp; Required-Ports, Assembly-Konnektoren).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der Port-basierten BSW-Service-Schnittstellen zwischen dem <em>Basic Software Mode Manager</em> (<code>BswM</code>) und dem <em>Communication Manager</em> (<code>ComM</code>) auf RTE-/VFB-Ebene.\n</li><li><strong>Funktionale Einordnung:</strong> Der <code>BswM</code> agiert als übergeordnete Entscheidungsinstanz (Mode Manager / Rule Engine), die systemweite Betriebsmodi bewertet. Der <code>ComM</code> fungiert als ausführender Kommunikationsdienstleister (Service Component). Über die dargestellten Schnittstellen erzwingt der <code>BswM</code> restriktive Energiespar- und Bordnetzschutz-Vorgaben:\n<ul class=\"fig-list\"><li><strong>Modus-Limitierung</strong> (<em>Mode Limitation</em>): Erzwingen des Zustands <code>COMM_NO_COMMUNICATION</code> auf Kanal- oder ECU-Ebene.\n</li><li><strong>Weck-Inhibition</strong> (<em>Wakeup Inhibition</em>): Unterbindung des aktiven Aufweckens des Bussystems durch das Steuergerät.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Rollen</h5>\n<ul class=\"fig-list\"><li><strong>Basic Software Mode Manager (<code>BswM</code>):</strong> Client-Komponente; besitzt Required Ports (Schnittstellen-Buchsen) zur Ausführung konfigurierter Mode-Arbitrierungsregeln.\n</li><li><strong>Com Manager (<code>ComM</code>):</strong> Server-Komponente (<code>Service Component</code>); stellt Provided Ports (Schnittstellen-Stecker) für Mode-Management-Dienste bereit.\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; Ports</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Schnittstelle (Client-Server, <code>IsService = true</code>)</th><th>Port-Muster (ComM P-Port)</th><th>BswM R-Port</th><th>Kardinalität</th><th>Relevante Operationen &amp; Parameter</th></tr></thead><tbody><tr><td><strong><code>ComM_ChannelWakeup</code></strong>&lt;br&gt;<em>(Aktiv bei <code>ComMWakeupInhibitionEnabled == true</code>)</em></td><td><code>CW000</code>, <code>CW001</code>, …&lt;br&gt;<em>(Präfix <code>CW_{channel_name}</code>)</em></td><td>R-Port</td><td>1 … n&lt;br&gt;<em>(1 Port pro <code>ComMChannel</code>)</em></td><td>• <code>PreventWakeUp(IN boolean Status)</code>&lt;br&gt;• <code>GetInhibitionStatus(OUT ComM_InhibitionStatusType* Status)</code></td></tr><tr><td><strong><code>ComM_ChannelLimitation</code></strong>&lt;br&gt;<em>(Aktiv bei <code>ComMModeLimitationEnabled == true</code>)</em></td><td><code>CL000</code>, <code>CL001</code>, …&lt;br&gt;<em>(Präfix <code>CL_{channel_name}</code>)</em></td><td>R-Port</td><td>1 … n&lt;br&gt;<em>(1 Port pro <code>ComMChannel</code>)</em></td><td>• <code>LimitChannelToNoComMode(IN boolean Status)</code>&lt;br&gt;• <code>GetInhibitionStatus(OUT ComM_InhibitionStatusType* Status)</code></td></tr><tr><td><strong><code>ComM_ECUModeLimitation</code></strong>&lt;br&gt;<em>(Aktiv bei <code>ComMModeLimitationEnabled == true</code>)</em></td><td><code>modeLimitation</code></td><td>R-Port</td><td>1&lt;br&gt;<em>(ECU-global)</em></td><td>• <code>LimitECUToNoComMode(IN boolean Status)</code>&lt;br&gt;• <code>ReadInhibitCounter(OUT uint16* CounterValue)</code>&lt;br&gt;• <code>ResetInhibitCounter()</code>&lt;br&gt;• <code>SetECUGroupClassification(IN ComM_InhibitionStatusType Status)</code></td></tr></tbody></table></div>\n<h5 class=\"fig-section-h5\">Formalismen &amp; Port Defined Argument Values</h5>\n<ul class=\"fig-list\"><li><strong>Port Defined Arguments:</strong> Die kanalspezifischen Ports (<code>CWxxx</code>, <code>CLxxx</code>) sind im RTE-Vertrag mit einem <em>Port Defined Argument Value</em> vom Typ <code>NetworkHandleType</code> versehen (<code>ComMChannelId</code>). Dadurch mappt die RTE den parameterlosen bzw. kanallosen Portaufruf des BswM direkt auf die zugrunde liegende C-API mit dem Kanalparameter (z. B. <code>ComM_PreventWakeUp(Channel, Status)</code> bzw. <code>ComM_LimitChannelToNoComMode(Channel, Status)</code>).\n</li><li><strong>Verbindungen:</strong> 1:1 Assembly Connectors (gestrichelte Verbindungslinien) zwischen BswM-R-Ports und ComM-P-Ports.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger &amp; Regel-Evaluation (BswM):</strong>\n<ul class=\"fig-list\"><li>Ein Zustandswechsel im BswM (z. B. Transition von <em>Run</em> nach <em>PostRun</em>, Unterspannungserkennung oder Diagnoseanforderung) feuert eine Regel.\n</li><li>Der BswM führt eine zugehörige <code>BswMAction</code> aus (z. B. <code>BswMComMChannelLimitation</code>, <code>BswMComMEcuModeLimitation</code> oder <code>BswMComMPreventWakeup</code>).\n</li></ul>\n</li><li><strong>Synchroner Client-Server-Aufruf (RTE):</strong>\n<ul class=\"fig-list\"><li>Der BswM ruft synchron die Operation auf (z. B. <code>Rte_Call_CL000_LimitChannelToNoComMode(TRUE)</code>).\n</li><li>Der Aufruf blockiert den BswM-Task-Kontext nur für die Dauer der lokalen Statusaktualisierung im <code>ComM</code>.\n</li></ul>\n</li><li><strong>Zustands- und Bitvektor-Aktualisierung im ComM:</strong>\n<ul class=\"fig-list\"><li>Der ComM aktualisiert seinen internen Statusbitvektor <code>ComM_InhibitionStatusType</code>:\n<ul class=\"fig-list\"><li>Bit 0 (<code>0x01</code>): <code>Wakeup Inhibition Active</code>\n</li><li>Bit 1 (<code>0x02</code>): <code>Limited To No Com</code>\n</li></ul>\n</li></ul>\n</li><li><strong>Auswirkung auf nachfolgende Modusanforderungen:</strong>\n<ul class=\"fig-list\"><li>Geht eine Anforderung von SW-Cs über <code>ComM_RequestComMode(User, COMM_FULL_COMMUNICATION)</code> ein:\n<ul class=\"fig-list\"><li><strong>Modus-Limitierung aktiv:</strong> Die Anfrage wird synchron mit dem Fehlerwert <code>COMM_E_MODE_LIMITATION</code> abgewiesen. Der interne Inhibit-Zähler (<code>InhibitCounter</code>) wird inkrementiert (und optional im NvM persistiert).\n</li><li><strong>Weck-Inhibition aktiv:</strong> Das Steuergerät darf bei externem Weckruf teilnehmen, initiiert jedoch bei internen Kommunikationswünschen kein aktives Aufwecken der Transceiver bzw. des Busses (<code>COMM_NO_WAKEUP</code>).\n</li></ul>\n</li></ul>\n</li><li><strong>Rückmeldung &amp; Indikation:</strong>\n<ul class=\"fig-list\"><li>Der BswM kann den aktuellen Status über <code>GetInhibitionStatus()</code> synchron abfragen.\n</li><li>Kanalzustandsänderungen, die sich aus der Limitierung ergeben (Übergang in <code>COMM_NO_COMMUNICATION</code>), meldet der ComM asynchron über <code>BswM_ComM_CurrentModeIndication()</code> an den BswM zurück.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Generierung &amp; Variantenkonfiguration:</strong>\n<ul class=\"fig-list\"><li>Fehlt in der EcuC-Konfiguration <code>ComMWakeupInhibitionEnabled = TRUE</code>, werden die Ports <code>CWxxx</code> und das Interface <code>ComM_ChannelWakeup</code> vom RTE-Generator nicht erzeugt (<code>[SWS_ComM_00742]</code>, <code>[SWS_ComM_01008]</code>).\n</li><li>Fehlt <code>ComMModeLimitationEnabled = TRUE</code>, entfallen die Ports <code>CLxxx</code>, <code>modeLimitation</code> sowie die zugehörigen Interfaces (<code>[SWS_ComM_00741]</code>, <code>[SWS_ComM_00743]</code>).\n</li></ul>\n</li><li><strong>BswM-Aktionskonfiguration:</strong>\n<ul class=\"fig-list\"><li>Im BswM-Modul müssen die Aktionen exakt auf die generierten R-Ports gemappt werden. Ein typischer Konfigurationsfehler ist das Setzen von <code>ComM_LimitECUToNoComMode</code> bei gleichzeitigem Erwarten von Restkommunikation auf Teilnetzwerken (PNCs) – die ECU-Limitierung überschreibt alle lokalen Kanal- und PNC-Freigaben.\n</li></ul>\n</li><li><strong>Fehlercodes &amp; Det:</strong>\n<ul class=\"fig-list\"><li>Aufrufe vor <code>ComM_Init()</code> liefern <code>E_NOT_OK</code> und erzeugen den Det-Fehler <code>COMM_E_UNINIT</code>.\n</li><li>Ein ungültiger Index in <code>NetworkHandleType</code> erzeugt <code>COMM_E_WRONG_PARAMETERS</code>.\n</li></ul>\n</li><li><strong>NvM-Kopplung:</strong>\n<ul class=\"fig-list\"><li>Ist <code>ComMGlobalNvMBlockDescriptor</code> konfiguriert, muss zur Erfassung abgewiesener Vollkommunikations-Anfragen der Inhibit-Counter über <code>ReadInhibitCounter()</code> / <code>ResetInhibitCounter()</code> im Fehlerspeicher- oder Shutdown-Pfad berücksichtigt werden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-60baeb1d1e869889", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR VFB- / UML-Komponentendiagramm mit nativer AUTOSAR Port-Interface-Notation (Ball-and-Socket / Provided- &amp; Required-Ports, Assembly-Konnektoren).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der Port-basierten BSW-Service-Schnittstellen zwischen dem <em>Basic Software Mode Manager</em> (<code>BswM</code>) und dem <em>Communication Manager</em> (<code>ComM</code>) auf RTE-/VFB-Ebene.\n</li><li><strong>Funktionale Einordnung:</strong> Der <code>BswM</code> agiert als übergeordnete Entscheidungsinstanz (Mode Manager / Rule Engine), die systemweite Betriebsmodi bewertet. Der <code>ComM</code> fungiert als ausführender Kommunikationsdienstleister (Service Component). Über die dargestellten Schnittstellen erzwingt der <code>BswM</code> restriktive Energiespar- und Bordnetzschutz-Vorgaben:\n<ul class=\"fig-list\"><li><strong>Modus-Limitierung</strong> (<em>Mode Limitation</em>): Erzwingen des Zustands <code>COMM_NO_COMMUNICATION</code> auf Kanal- oder ECU-Ebene.\n</li><li><strong>Weck-Inhibition</strong> (<em>Wakeup Inhibition</em>): Unterbindung des aktiven Aufweckens des Bussystems durch das Steuergerät.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Rollen</h5>\n<ul class=\"fig-list\"><li><strong>Basic Software Mode Manager (<code>BswM</code>):</strong> Client-Komponente; besitzt Required Ports (Schnittstellen-Buchsen) zur Ausführung konfigurierter Mode-Arbitrierungsregeln.\n</li><li><strong>Com Manager (<code>ComM</code>):</strong> Server-Komponente (<code>Service Component</code>); stellt Provided Ports (Schnittstellen-Stecker) für Mode-Management-Dienste bereit.\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; Ports</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Schnittstelle (Client-Server, <code>IsService = true</code>)</th><th>Port-Muster (ComM P-Port)</th><th>BswM R-Port</th><th>Kardinalität</th><th>Relevante Operationen &amp; Parameter</th></tr></thead><tbody><tr><td><strong><code>ComM_ChannelWakeup</code></strong>&lt;br&gt;<em>(Aktiv bei <code>ComMWakeupInhibitionEnabled == true</code>)</em></td><td><code>CW000</code>, <code>CW001</code>, …&lt;br&gt;<em>(Präfix <code>CW_{channel_name}</code>)</em></td><td>R-Port</td><td>1 … n&lt;br&gt;<em>(1 Port pro <code>ComMChannel</code>)</em></td><td>• <code>PreventWakeUp(IN boolean Status)</code>&lt;br&gt;• <code>GetInhibitionStatus(OUT ComM_InhibitionStatusType* Status)</code></td></tr><tr><td><strong><code>ComM_ChannelLimitation</code></strong>&lt;br&gt;<em>(Aktiv bei <code>ComMModeLimitationEnabled == true</code>)</em></td><td><code>CL000</code>, <code>CL001</code>, …&lt;br&gt;<em>(Präfix <code>CL_{channel_name}</code>)</em></td><td>R-Port</td><td>1 … n&lt;br&gt;<em>(1 Port pro <code>ComMChannel</code>)</em></td><td>• <code>LimitChannelToNoComMode(IN boolean Status)</code>&lt;br&gt;• <code>GetInhibitionStatus(OUT ComM_InhibitionStatusType* Status)</code></td></tr><tr><td><strong><code>ComM_ECUModeLimitation</code></strong>&lt;br&gt;<em>(Aktiv bei <code>ComMModeLimitationEnabled == true</code>)</em></td><td><code>modeLimitation</code></td><td>R-Port</td><td>1&lt;br&gt;<em>(ECU-global)</em></td><td>• <code>LimitECUToNoComMode(IN boolean Status)</code>&lt;br&gt;• <code>ReadInhibitCounter(OUT uint16* CounterValue)</code>&lt;br&gt;• <code>ResetInhibitCounter()</code>&lt;br&gt;• <code>SetECUGroupClassification(IN ComM_InhibitionStatusType Status)</code></td></tr></tbody></table></div>\n<h5 class=\"fig-section-h5\">Formalismen &amp; Port Defined Argument Values</h5>\n<ul class=\"fig-list\"><li><strong>Port Defined Arguments:</strong> Die kanalspezifischen Ports (<code>CWxxx</code>, <code>CLxxx</code>) sind im RTE-Vertrag mit einem <em>Port Defined Argument Value</em> vom Typ <code>NetworkHandleType</code> versehen (<code>ComMChannelId</code>). Dadurch mappt die RTE den parameterlosen bzw. kanallosen Portaufruf des BswM direkt auf die zugrunde liegende C-API mit dem Kanalparameter (z. B. <code>ComM_PreventWakeUp(Channel, Status)</code> bzw. <code>ComM_LimitChannelToNoComMode(Channel, Status)</code>).\n</li><li><strong>Verbindungen:</strong> 1:1 Assembly Connectors (gestrichelte Verbindungslinien) zwischen BswM-R-Ports und ComM-P-Ports.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger &amp; Regel-Evaluation (BswM):</strong>\n<ul class=\"fig-list\"><li>Ein Zustandswechsel im BswM (z. B. Transition von <em>Run</em> nach <em>PostRun</em>, Unterspannungserkennung oder Diagnoseanforderung) feuert eine Regel.\n</li><li>Der BswM führt eine zugehörige <code>BswMAction</code> aus (z. B. <code>BswMComMChannelLimitation</code>, <code>BswMComMEcuModeLimitation</code> oder <code>BswMComMPreventWakeup</code>).\n</li></ul>\n</li><li><strong>Synchroner Client-Server-Aufruf (RTE):</strong>\n<ul class=\"fig-list\"><li>Der BswM ruft synchron die Operation auf (z. B. <code>Rte_Call_CL000_LimitChannelToNoComMode(TRUE)</code>).\n</li><li>Der Aufruf blockiert den BswM-Task-Kontext nur für die Dauer der lokalen Statusaktualisierung im <code>ComM</code>.\n</li></ul>\n</li><li><strong>Zustands- und Bitvektor-Aktualisierung im ComM:</strong>\n<ul class=\"fig-list\"><li>Der ComM aktualisiert seinen internen Statusbitvektor <code>ComM_InhibitionStatusType</code>:\n<ul class=\"fig-list\"><li>Bit 0 (<code>0x01</code>): <code>Wakeup Inhibition Active</code>\n</li><li>Bit 1 (<code>0x02</code>): <code>Limited To No Com</code>\n</li></ul>\n</li></ul>\n</li><li><strong>Auswirkung auf nachfolgende Modusanforderungen:</strong>\n<ul class=\"fig-list\"><li>Geht eine Anforderung von SW-Cs über <code>ComM_RequestComMode(User, COMM_FULL_COMMUNICATION)</code> ein:\n<ul class=\"fig-list\"><li><strong>Modus-Limitierung aktiv:</strong> Die Anfrage wird synchron mit dem Fehlerwert <code>COMM_E_MODE_LIMITATION</code> abgewiesen. Der interne Inhibit-Zähler (<code>InhibitCounter</code>) wird inkrementiert (und optional im NvM persistiert).\n</li><li><strong>Weck-Inhibition aktiv:</strong> Das Steuergerät darf bei externem Weckruf teilnehmen, initiiert jedoch bei internen Kommunikationswünschen kein aktives Aufwecken der Transceiver bzw. des Busses (<code>COMM_NO_WAKEUP</code>).\n</li></ul>\n</li></ul>\n</li><li><strong>Rückmeldung &amp; Indikation:</strong>\n<ul class=\"fig-list\"><li>Der BswM kann den aktuellen Status über <code>GetInhibitionStatus()</code> synchron abfragen.\n</li><li>Kanalzustandsänderungen, die sich aus der Limitierung ergeben (Übergang in <code>COMM_NO_COMMUNICATION</code>), meldet der ComM asynchron über <code>BswM_ComM_CurrentModeIndication()</code> an den BswM zurück.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Generierung &amp; Variantenkonfiguration:</strong>\n<ul class=\"fig-list\"><li>Fehlt in der EcuC-Konfiguration <code>ComMWakeupInhibitionEnabled = TRUE</code>, werden die Ports <code>CWxxx</code> und das Interface <code>ComM_ChannelWakeup</code> vom RTE-Generator nicht erzeugt (<code>[SWS_ComM_00742]</code>, <code>[SWS_ComM_01008]</code>).\n</li><li>Fehlt <code>ComMModeLimitationEnabled = TRUE</code>, entfallen die Ports <code>CLxxx</code>, <code>modeLimitation</code> sowie die zugehörigen Interfaces (<code>[SWS_ComM_00741]</code>, <code>[SWS_ComM_00743]</code>).\n</li></ul>\n</li><li><strong>BswM-Aktionskonfiguration:</strong>\n<ul class=\"fig-list\"><li>Im BswM-Modul müssen die Aktionen exakt auf die generierten R-Ports gemappt werden. Ein typischer Konfigurationsfehler ist das Setzen von <code>ComM_LimitECUToNoComMode</code> bei gleichzeitigem Erwarten von Restkommunikation auf Teilnetzwerken (PNCs) – die ECU-Limitierung überschreibt alle lokalen Kanal- und PNC-Freigaben.\n</li></ul>\n</li><li><strong>Fehlercodes &amp; Det:</strong>\n<ul class=\"fig-list\"><li>Aufrufe vor <code>ComM_Init()</code> liefern <code>E_NOT_OK</code> und erzeugen den Det-Fehler <code>COMM_E_UNINIT</code>.\n</li><li>Ein ungültiger Index in <code>NetworkHandleType</code> erzeugt <code>COMM_E_WRONG_PARAMETERS</code>.\n</li></ul>\n</li><li><strong>NvM-Kopplung:</strong>\n<ul class=\"fig-list\"><li>Ist <code>ComMGlobalNvMBlockDescriptor</code> konfiguriert, muss zur Erfassung abgewiesener Vollkommunikations-Anfragen der Inhibit-Counter über <code>ReadInhibitCounter()</code> / <code>ResetInhibitCounter()</code> im Fehlerspeicher- oder Shutdown-Pfad berücksichtigt werden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-917fa846b1fedadb", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR VFB- / UML-Komponentendiagramm mit nativer AUTOSAR Port-Interface-Notation (Ball-and-Socket / Provided- &amp; Required-Ports, Assembly-Konnektoren).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der Port-basierten BSW-Service-Schnittstellen zwischen dem <em>Basic Software Mode Manager</em> (<code>BswM</code>) und dem <em>Communication Manager</em> (<code>ComM</code>) auf RTE-/VFB-Ebene.\n</li><li><strong>Funktionale Einordnung:</strong> Der <code>BswM</code> agiert als übergeordnete Entscheidungsinstanz (Mode Manager / Rule Engine), die systemweite Betriebsmodi bewertet. Der <code>ComM</code> fungiert als ausführender Kommunikationsdienstleister (Service Component). Über die dargestellten Schnittstellen erzwingt der <code>BswM</code> restriktive Energiespar- und Bordnetzschutz-Vorgaben:\n<ul class=\"fig-list\"><li><strong>Modus-Limitierung</strong> (<em>Mode Limitation</em>): Erzwingen des Zustands <code>COMM_NO_COMMUNICATION</code> auf Kanal- oder ECU-Ebene.\n</li><li><strong>Weck-Inhibition</strong> (<em>Wakeup Inhibition</em>): Unterbindung des aktiven Aufweckens des Bussystems durch das Steuergerät.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Rollen</h5>\n<ul class=\"fig-list\"><li><strong>Basic Software Mode Manager (<code>BswM</code>):</strong> Client-Komponente; besitzt Required Ports (Schnittstellen-Buchsen) zur Ausführung konfigurierter Mode-Arbitrierungsregeln.\n</li><li><strong>Com Manager (<code>ComM</code>):</strong> Server-Komponente (<code>Service Component</code>); stellt Provided Ports (Schnittstellen-Stecker) für Mode-Management-Dienste bereit.\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; Ports</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Schnittstelle (Client-Server, <code>IsService = true</code>)</th><th>Port-Muster (ComM P-Port)</th><th>BswM R-Port</th><th>Kardinalität</th><th>Relevante Operationen &amp; Parameter</th></tr></thead><tbody><tr><td><strong><code>ComM_ChannelWakeup</code></strong>&lt;br&gt;<em>(Aktiv bei <code>ComMWakeupInhibitionEnabled == true</code>)</em></td><td><code>CW000</code>, <code>CW001</code>, …&lt;br&gt;<em>(Präfix <code>CW_{channel_name}</code>)</em></td><td>R-Port</td><td>1 … n&lt;br&gt;<em>(1 Port pro <code>ComMChannel</code>)</em></td><td>• <code>PreventWakeUp(IN boolean Status)</code>&lt;br&gt;• <code>GetInhibitionStatus(OUT ComM_InhibitionStatusType* Status)</code></td></tr><tr><td><strong><code>ComM_ChannelLimitation</code></strong>&lt;br&gt;<em>(Aktiv bei <code>ComMModeLimitationEnabled == true</code>)</em></td><td><code>CL000</code>, <code>CL001</code>, …&lt;br&gt;<em>(Präfix <code>CL_{channel_name}</code>)</em></td><td>R-Port</td><td>1 … n&lt;br&gt;<em>(1 Port pro <code>ComMChannel</code>)</em></td><td>• <code>LimitChannelToNoComMode(IN boolean Status)</code>&lt;br&gt;• <code>GetInhibitionStatus(OUT ComM_InhibitionStatusType* Status)</code></td></tr><tr><td><strong><code>ComM_ECUModeLimitation</code></strong>&lt;br&gt;<em>(Aktiv bei <code>ComMModeLimitationEnabled == true</code>)</em></td><td><code>modeLimitation</code></td><td>R-Port</td><td>1&lt;br&gt;<em>(ECU-global)</em></td><td>• <code>LimitECUToNoComMode(IN boolean Status)</code>&lt;br&gt;• <code>ReadInhibitCounter(OUT uint16* CounterValue)</code>&lt;br&gt;• <code>ResetInhibitCounter()</code>&lt;br&gt;• <code>SetECUGroupClassification(IN ComM_InhibitionStatusType Status)</code></td></tr></tbody></table></div>\n<h5 class=\"fig-section-h5\">Formalismen &amp; Port Defined Argument Values</h5>\n<ul class=\"fig-list\"><li><strong>Port Defined Arguments:</strong> Die kanalspezifischen Ports (<code>CWxxx</code>, <code>CLxxx</code>) sind im RTE-Vertrag mit einem <em>Port Defined Argument Value</em> vom Typ <code>NetworkHandleType</code> versehen (<code>ComMChannelId</code>). Dadurch mappt die RTE den parameterlosen bzw. kanallosen Portaufruf des BswM direkt auf die zugrunde liegende C-API mit dem Kanalparameter (z. B. <code>ComM_PreventWakeUp(Channel, Status)</code> bzw. <code>ComM_LimitChannelToNoComMode(Channel, Status)</code>).\n</li><li><strong>Verbindungen:</strong> 1:1 Assembly Connectors (gestrichelte Verbindungslinien) zwischen BswM-R-Ports und ComM-P-Ports.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger &amp; Regel-Evaluation (BswM):</strong>\n<ul class=\"fig-list\"><li>Ein Zustandswechsel im BswM (z. B. Transition von <em>Run</em> nach <em>PostRun</em>, Unterspannungserkennung oder Diagnoseanforderung) feuert eine Regel.\n</li><li>Der BswM führt eine zugehörige <code>BswMAction</code> aus (z. B. <code>BswMComMChannelLimitation</code>, <code>BswMComMEcuModeLimitation</code> oder <code>BswMComMPreventWakeup</code>).\n</li></ul>\n</li><li><strong>Synchroner Client-Server-Aufruf (RTE):</strong>\n<ul class=\"fig-list\"><li>Der BswM ruft synchron die Operation auf (z. B. <code>Rte_Call_CL000_LimitChannelToNoComMode(TRUE)</code>).\n</li><li>Der Aufruf blockiert den BswM-Task-Kontext nur für die Dauer der lokalen Statusaktualisierung im <code>ComM</code>.\n</li></ul>\n</li><li><strong>Zustands- und Bitvektor-Aktualisierung im ComM:</strong>\n<ul class=\"fig-list\"><li>Der ComM aktualisiert seinen internen Statusbitvektor <code>ComM_InhibitionStatusType</code>:\n<ul class=\"fig-list\"><li>Bit 0 (<code>0x01</code>): <code>Wakeup Inhibition Active</code>\n</li><li>Bit 1 (<code>0x02</code>): <code>Limited To No Com</code>\n</li></ul>\n</li></ul>\n</li><li><strong>Auswirkung auf nachfolgende Modusanforderungen:</strong>\n<ul class=\"fig-list\"><li>Geht eine Anforderung von SW-Cs über <code>ComM_RequestComMode(User, COMM_FULL_COMMUNICATION)</code> ein:\n<ul class=\"fig-list\"><li><strong>Modus-Limitierung aktiv:</strong> Die Anfrage wird synchron mit dem Fehlerwert <code>COMM_E_MODE_LIMITATION</code> abgewiesen. Der interne Inhibit-Zähler (<code>InhibitCounter</code>) wird inkrementiert (und optional im NvM persistiert).\n</li><li><strong>Weck-Inhibition aktiv:</strong> Das Steuergerät darf bei externem Weckruf teilnehmen, initiiert jedoch bei internen Kommunikationswünschen kein aktives Aufwecken der Transceiver bzw. des Busses (<code>COMM_NO_WAKEUP</code>).\n</li></ul>\n</li></ul>\n</li><li><strong>Rückmeldung &amp; Indikation:</strong>\n<ul class=\"fig-list\"><li>Der BswM kann den aktuellen Status über <code>GetInhibitionStatus()</code> synchron abfragen.\n</li><li>Kanalzustandsänderungen, die sich aus der Limitierung ergeben (Übergang in <code>COMM_NO_COMMUNICATION</code>), meldet der ComM asynchron über <code>BswM_ComM_CurrentModeIndication()</code> an den BswM zurück.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Generierung &amp; Variantenkonfiguration:</strong>\n<ul class=\"fig-list\"><li>Fehlt in der EcuC-Konfiguration <code>ComMWakeupInhibitionEnabled = TRUE</code>, werden die Ports <code>CWxxx</code> und das Interface <code>ComM_ChannelWakeup</code> vom RTE-Generator nicht erzeugt (<code>[SWS_ComM_00742]</code>, <code>[SWS_ComM_01008]</code>).\n</li><li>Fehlt <code>ComMModeLimitationEnabled = TRUE</code>, entfallen die Ports <code>CLxxx</code>, <code>modeLimitation</code> sowie die zugehörigen Interfaces (<code>[SWS_ComM_00741]</code>, <code>[SWS_ComM_00743]</code>).\n</li></ul>\n</li><li><strong>BswM-Aktionskonfiguration:</strong>\n<ul class=\"fig-list\"><li>Im BswM-Modul müssen die Aktionen exakt auf die generierten R-Ports gemappt werden. Ein typischer Konfigurationsfehler ist das Setzen von <code>ComM_LimitECUToNoComMode</code> bei gleichzeitigem Erwarten von Restkommunikation auf Teilnetzwerken (PNCs) – die ECU-Limitierung überschreibt alle lokalen Kanal- und PNC-Freigaben.\n</li></ul>\n</li><li><strong>Fehlercodes &amp; Det:</strong>\n<ul class=\"fig-list\"><li>Aufrufe vor <code>ComM_Init()</code> liefern <code>E_NOT_OK</code> und erzeugen den Det-Fehler <code>COMM_E_UNINIT</code>.\n</li><li>Ein ungültiger Index in <code>NetworkHandleType</code> erzeugt <code>COMM_E_WRONG_PARAMETERS</code>.\n</li></ul>\n</li><li><strong>NvM-Kopplung:</strong>\n<ul class=\"fig-list\"><li>Ist <code>ComMGlobalNvMBlockDescriptor</code> konfiguriert, muss zur Erfassung abgewiesener Vollkommunikations-Anfragen der Inhibit-Counter über <code>ReadInhibitCounter()</code> / <code>ResetInhibitCounter()</code> im Fehlerspeicher- oder Shutdown-Pfad berücksichtigt werden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-7eaca75fb6197b53", "releases": ["R20-11", "R21-11", "R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR VFB- / UML-Komponentendiagramm mit nativer AUTOSAR Port-Interface-Notation (Ball-and-Socket / Provided- &amp; Required-Ports, Assembly-Konnektoren).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der Port-basierten BSW-Service-Schnittstellen zwischen dem <em>Basic Software Mode Manager</em> (<code>BswM</code>) und dem <em>Communication Manager</em> (<code>ComM</code>) auf RTE-/VFB-Ebene.\n</li><li><strong>Funktionale Einordnung:</strong> Der <code>BswM</code> agiert als übergeordnete Entscheidungsinstanz (Mode Manager / Rule Engine), die systemweite Betriebsmodi bewertet. Der <code>ComM</code> fungiert als ausführender Kommunikationsdienstleister (Service Component). Über die dargestellten Schnittstellen erzwingt der <code>BswM</code> restriktive Energiespar- und Bordnetzschutz-Vorgaben:\n<ul class=\"fig-list\"><li><strong>Modus-Limitierung</strong> (<em>Mode Limitation</em>): Erzwingen des Zustands <code>COMM_NO_COMMUNICATION</code> auf Kanal- oder ECU-Ebene.\n</li><li><strong>Weck-Inhibition</strong> (<em>Wakeup Inhibition</em>): Unterbindung des aktiven Aufweckens des Bussystems durch das Steuergerät.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Rollen</h5>\n<ul class=\"fig-list\"><li><strong>Basic Software Mode Manager (<code>BswM</code>):</strong> Client-Komponente; besitzt Required Ports (Schnittstellen-Buchsen) zur Ausführung konfigurierter Mode-Arbitrierungsregeln.\n</li><li><strong>Com Manager (<code>ComM</code>):</strong> Server-Komponente (<code>Service Component</code>); stellt Provided Ports (Schnittstellen-Stecker) für Mode-Management-Dienste bereit.\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; Ports</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Schnittstelle (Client-Server, <code>IsService = true</code>)</th><th>Port-Muster (ComM P-Port)</th><th>BswM R-Port</th><th>Kardinalität</th><th>Relevante Operationen &amp; Parameter</th></tr></thead><tbody><tr><td><strong><code>ComM_ChannelWakeup</code></strong>&lt;br&gt;<em>(Aktiv bei <code>ComMWakeupInhibitionEnabled == true</code>)</em></td><td><code>CW000</code>, <code>CW001</code>, …&lt;br&gt;<em>(Präfix <code>CW_{channel_name}</code>)</em></td><td>R-Port</td><td>1 … n&lt;br&gt;<em>(1 Port pro <code>ComMChannel</code>)</em></td><td>• <code>PreventWakeUp(IN boolean Status)</code>&lt;br&gt;• <code>GetInhibitionStatus(OUT ComM_InhibitionStatusType* Status)</code></td></tr><tr><td><strong><code>ComM_ChannelLimitation</code></strong>&lt;br&gt;<em>(Aktiv bei <code>ComMModeLimitationEnabled == true</code>)</em></td><td><code>CL000</code>, <code>CL001</code>, …&lt;br&gt;<em>(Präfix <code>CL_{channel_name}</code>)</em></td><td>R-Port</td><td>1 … n&lt;br&gt;<em>(1 Port pro <code>ComMChannel</code>)</em></td><td>• <code>LimitChannelToNoComMode(IN boolean Status)</code>&lt;br&gt;• <code>GetInhibitionStatus(OUT ComM_InhibitionStatusType* Status)</code></td></tr><tr><td><strong><code>ComM_ECUModeLimitation</code></strong>&lt;br&gt;<em>(Aktiv bei <code>ComMModeLimitationEnabled == true</code>)</em></td><td><code>modeLimitation</code></td><td>R-Port</td><td>1&lt;br&gt;<em>(ECU-global)</em></td><td>• <code>LimitECUToNoComMode(IN boolean Status)</code>&lt;br&gt;• <code>ReadInhibitCounter(OUT uint16* CounterValue)</code>&lt;br&gt;• <code>ResetInhibitCounter()</code>&lt;br&gt;• <code>SetECUGroupClassification(IN ComM_InhibitionStatusType Status)</code></td></tr></tbody></table></div>\n<h5 class=\"fig-section-h5\">Formalismen &amp; Port Defined Argument Values</h5>\n<ul class=\"fig-list\"><li><strong>Port Defined Arguments:</strong> Die kanalspezifischen Ports (<code>CWxxx</code>, <code>CLxxx</code>) sind im RTE-Vertrag mit einem <em>Port Defined Argument Value</em> vom Typ <code>NetworkHandleType</code> versehen (<code>ComMChannelId</code>). Dadurch mappt die RTE den parameterlosen bzw. kanallosen Portaufruf des BswM direkt auf die zugrunde liegende C-API mit dem Kanalparameter (z. B. <code>ComM_PreventWakeUp(Channel, Status)</code> bzw. <code>ComM_LimitChannelToNoComMode(Channel, Status)</code>).\n</li><li><strong>Verbindungen:</strong> 1:1 Assembly Connectors (gestrichelte Verbindungslinien) zwischen BswM-R-Ports und ComM-P-Ports.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger &amp; Regel-Evaluation (BswM):</strong>\n<ul class=\"fig-list\"><li>Ein Zustandswechsel im BswM (z. B. Transition von <em>Run</em> nach <em>PostRun</em>, Unterspannungserkennung oder Diagnoseanforderung) feuert eine Regel.\n</li><li>Der BswM führt eine zugehörige <code>BswMAction</code> aus (z. B. <code>BswMComMChannelLimitation</code>, <code>BswMComMEcuModeLimitation</code> oder <code>BswMComMPreventWakeup</code>).\n</li></ul>\n</li><li><strong>Synchroner Client-Server-Aufruf (RTE):</strong>\n<ul class=\"fig-list\"><li>Der BswM ruft synchron die Operation auf (z. B. <code>Rte_Call_CL000_LimitChannelToNoComMode(TRUE)</code>).\n</li><li>Der Aufruf blockiert den BswM-Task-Kontext nur für die Dauer der lokalen Statusaktualisierung im <code>ComM</code>.\n</li></ul>\n</li><li><strong>Zustands- und Bitvektor-Aktualisierung im ComM:</strong>\n<ul class=\"fig-list\"><li>Der ComM aktualisiert seinen internen Statusbitvektor <code>ComM_InhibitionStatusType</code>:\n<ul class=\"fig-list\"><li>Bit 0 (<code>0x01</code>): <code>Wakeup Inhibition Active</code>\n</li><li>Bit 1 (<code>0x02</code>): <code>Limited To No Com</code>\n</li></ul>\n</li></ul>\n</li><li><strong>Auswirkung auf nachfolgende Modusanforderungen:</strong>\n<ul class=\"fig-list\"><li>Geht eine Anforderung von SW-Cs über <code>ComM_RequestComMode(User, COMM_FULL_COMMUNICATION)</code> ein:\n<ul class=\"fig-list\"><li><strong>Modus-Limitierung aktiv:</strong> Die Anfrage wird synchron mit dem Fehlerwert <code>COMM_E_MODE_LIMITATION</code> abgewiesen. Der interne Inhibit-Zähler (<code>InhibitCounter</code>) wird inkrementiert (und optional im NvM persistiert).\n</li><li><strong>Weck-Inhibition aktiv:</strong> Das Steuergerät darf bei externem Weckruf teilnehmen, initiiert jedoch bei internen Kommunikationswünschen kein aktives Aufwecken der Transceiver bzw. des Busses (<code>COMM_NO_WAKEUP</code>).\n</li></ul>\n</li></ul>\n</li><li><strong>Rückmeldung &amp; Indikation:</strong>\n<ul class=\"fig-list\"><li>Der BswM kann den aktuellen Status über <code>GetInhibitionStatus()</code> synchron abfragen.\n</li><li>Kanalzustandsänderungen, die sich aus der Limitierung ergeben (Übergang in <code>COMM_NO_COMMUNICATION</code>), meldet der ComM asynchron über <code>BswM_ComM_CurrentModeIndication()</code> an den BswM zurück.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Generierung &amp; Variantenkonfiguration:</strong>\n<ul class=\"fig-list\"><li>Fehlt in der EcuC-Konfiguration <code>ComMWakeupInhibitionEnabled = TRUE</code>, werden die Ports <code>CWxxx</code> und das Interface <code>ComM_ChannelWakeup</code> vom RTE-Generator nicht erzeugt (<code>[SWS_ComM_00742]</code>, <code>[SWS_ComM_01008]</code>).\n</li><li>Fehlt <code>ComMModeLimitationEnabled = TRUE</code>, entfallen die Ports <code>CLxxx</code>, <code>modeLimitation</code> sowie die zugehörigen Interfaces (<code>[SWS_ComM_00741]</code>, <code>[SWS_ComM_00743]</code>).\n</li></ul>\n</li><li><strong>BswM-Aktionskonfiguration:</strong>\n<ul class=\"fig-list\"><li>Im BswM-Modul müssen die Aktionen exakt auf die generierten R-Ports gemappt werden. Ein typischer Konfigurationsfehler ist das Setzen von <code>ComM_LimitECUToNoComMode</code> bei gleichzeitigem Erwarten von Restkommunikation auf Teilnetzwerken (PNCs) – die ECU-Limitierung überschreibt alle lokalen Kanal- und PNC-Freigaben.\n</li></ul>\n</li><li><strong>Fehlercodes &amp; Det:</strong>\n<ul class=\"fig-list\"><li>Aufrufe vor <code>ComM_Init()</code> liefern <code>E_NOT_OK</code> und erzeugen den Det-Fehler <code>COMM_E_UNINIT</code>.\n</li><li>Ein ungültiger Index in <code>NetworkHandleType</code> erzeugt <code>COMM_E_WRONG_PARAMETERS</code>.\n</li></ul>\n</li><li><strong>NvM-Kopplung:</strong>\n<ul class=\"fig-list\"><li>Ist <code>ComMGlobalNvMBlockDescriptor</code> konfiguriert, muss zur Erfassung abgewiesener Vollkommunikations-Anfragen der Inhibit-Counter über <code>ReadInhibitCounter()</code> / <code>ResetInhibitCounter()</code> im Fehlerspeicher- oder Shutdown-Pfad berücksichtigt werden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-f22d9f4acbc7d34a", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR VFB- / UML-Komponentendiagramm mit nativer AUTOSAR Port-Interface-Notation (Ball-and-Socket / Provided- &amp; Required-Ports, Assembly-Konnektoren).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der Port-basierten BSW-Service-Schnittstellen zwischen dem <em>Basic Software Mode Manager</em> (<code>BswM</code>) und dem <em>Communication Manager</em> (<code>ComM</code>) auf RTE-/VFB-Ebene.\n</li><li><strong>Funktionale Einordnung:</strong> Der <code>BswM</code> agiert als übergeordnete Entscheidungsinstanz (Mode Manager / Rule Engine), die systemweite Betriebsmodi bewertet. Der <code>ComM</code> fungiert als ausführender Kommunikationsdienstleister (Service Component). Über die dargestellten Schnittstellen erzwingt der <code>BswM</code> restriktive Energiespar- und Bordnetzschutz-Vorgaben:\n<ul class=\"fig-list\"><li><strong>Modus-Limitierung</strong> (<em>Mode Limitation</em>): Erzwingen des Zustands <code>COMM_NO_COMMUNICATION</code> auf Kanal- oder ECU-Ebene.\n</li><li><strong>Weck-Inhibition</strong> (<em>Wakeup Inhibition</em>): Unterbindung des aktiven Aufweckens des Bussystems durch das Steuergerät.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Rollen</h5>\n<ul class=\"fig-list\"><li><strong>Basic Software Mode Manager (<code>BswM</code>):</strong> Client-Komponente; besitzt Required Ports (Schnittstellen-Buchsen) zur Ausführung konfigurierter Mode-Arbitrierungsregeln.\n</li><li><strong>Com Manager (<code>ComM</code>):</strong> Server-Komponente (<code>Service Component</code>); stellt Provided Ports (Schnittstellen-Stecker) für Mode-Management-Dienste bereit.\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; Ports</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Schnittstelle (Client-Server, <code>IsService = true</code>)</th><th>Port-Muster (ComM P-Port)</th><th>BswM R-Port</th><th>Kardinalität</th><th>Relevante Operationen &amp; Parameter</th></tr></thead><tbody><tr><td><strong><code>ComM_ChannelWakeup</code></strong>&lt;br&gt;<em>(Aktiv bei <code>ComMWakeupInhibitionEnabled == true</code>)</em></td><td><code>CW000</code>, <code>CW001</code>, …&lt;br&gt;<em>(Präfix <code>CW_{channel_name}</code>)</em></td><td>R-Port</td><td>1 … n&lt;br&gt;<em>(1 Port pro <code>ComMChannel</code>)</em></td><td>• <code>PreventWakeUp(IN boolean Status)</code>&lt;br&gt;• <code>GetInhibitionStatus(OUT ComM_InhibitionStatusType* Status)</code></td></tr><tr><td><strong><code>ComM_ChannelLimitation</code></strong>&lt;br&gt;<em>(Aktiv bei <code>ComMModeLimitationEnabled == true</code>)</em></td><td><code>CL000</code>, <code>CL001</code>, …&lt;br&gt;<em>(Präfix <code>CL_{channel_name}</code>)</em></td><td>R-Port</td><td>1 … n&lt;br&gt;<em>(1 Port pro <code>ComMChannel</code>)</em></td><td>• <code>LimitChannelToNoComMode(IN boolean Status)</code>&lt;br&gt;• <code>GetInhibitionStatus(OUT ComM_InhibitionStatusType* Status)</code></td></tr><tr><td><strong><code>ComM_ECUModeLimitation</code></strong>&lt;br&gt;<em>(Aktiv bei <code>ComMModeLimitationEnabled == true</code>)</em></td><td><code>modeLimitation</code></td><td>R-Port</td><td>1&lt;br&gt;<em>(ECU-global)</em></td><td>• <code>LimitECUToNoComMode(IN boolean Status)</code>&lt;br&gt;• <code>ReadInhibitCounter(OUT uint16* CounterValue)</code>&lt;br&gt;• <code>ResetInhibitCounter()</code>&lt;br&gt;• <code>SetECUGroupClassification(IN ComM_InhibitionStatusType Status)</code></td></tr></tbody></table></div>\n<h5 class=\"fig-section-h5\">Formalismen &amp; Port Defined Argument Values</h5>\n<ul class=\"fig-list\"><li><strong>Port Defined Arguments:</strong> Die kanalspezifischen Ports (<code>CWxxx</code>, <code>CLxxx</code>) sind im RTE-Vertrag mit einem <em>Port Defined Argument Value</em> vom Typ <code>NetworkHandleType</code> versehen (<code>ComMChannelId</code>). Dadurch mappt die RTE den parameterlosen bzw. kanallosen Portaufruf des BswM direkt auf die zugrunde liegende C-API mit dem Kanalparameter (z. B. <code>ComM_PreventWakeUp(Channel, Status)</code> bzw. <code>ComM_LimitChannelToNoComMode(Channel, Status)</code>).\n</li><li><strong>Verbindungen:</strong> 1:1 Assembly Connectors (gestrichelte Verbindungslinien) zwischen BswM-R-Ports und ComM-P-Ports.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger &amp; Regel-Evaluation (BswM):</strong>\n<ul class=\"fig-list\"><li>Ein Zustandswechsel im BswM (z. B. Transition von <em>Run</em> nach <em>PostRun</em>, Unterspannungserkennung oder Diagnoseanforderung) feuert eine Regel.\n</li><li>Der BswM führt eine zugehörige <code>BswMAction</code> aus (z. B. <code>BswMComMChannelLimitation</code>, <code>BswMComMEcuModeLimitation</code> oder <code>BswMComMPreventWakeup</code>).\n</li></ul>\n</li><li><strong>Synchroner Client-Server-Aufruf (RTE):</strong>\n<ul class=\"fig-list\"><li>Der BswM ruft synchron die Operation auf (z. B. <code>Rte_Call_CL000_LimitChannelToNoComMode(TRUE)</code>).\n</li><li>Der Aufruf blockiert den BswM-Task-Kontext nur für die Dauer der lokalen Statusaktualisierung im <code>ComM</code>.\n</li></ul>\n</li><li><strong>Zustands- und Bitvektor-Aktualisierung im ComM:</strong>\n<ul class=\"fig-list\"><li>Der ComM aktualisiert seinen internen Statusbitvektor <code>ComM_InhibitionStatusType</code>:\n<ul class=\"fig-list\"><li>Bit 0 (<code>0x01</code>): <code>Wakeup Inhibition Active</code>\n</li><li>Bit 1 (<code>0x02</code>): <code>Limited To No Com</code>\n</li></ul>\n</li></ul>\n</li><li><strong>Auswirkung auf nachfolgende Modusanforderungen:</strong>\n<ul class=\"fig-list\"><li>Geht eine Anforderung von SW-Cs über <code>ComM_RequestComMode(User, COMM_FULL_COMMUNICATION)</code> ein:\n<ul class=\"fig-list\"><li><strong>Modus-Limitierung aktiv:</strong> Die Anfrage wird synchron mit dem Fehlerwert <code>COMM_E_MODE_LIMITATION</code> abgewiesen. Der interne Inhibit-Zähler (<code>InhibitCounter</code>) wird inkrementiert (und optional im NvM persistiert).\n</li><li><strong>Weck-Inhibition aktiv:</strong> Das Steuergerät darf bei externem Weckruf teilnehmen, initiiert jedoch bei internen Kommunikationswünschen kein aktives Aufwecken der Transceiver bzw. des Busses (<code>COMM_NO_WAKEUP</code>).\n</li></ul>\n</li></ul>\n</li><li><strong>Rückmeldung &amp; Indikation:</strong>\n<ul class=\"fig-list\"><li>Der BswM kann den aktuellen Status über <code>GetInhibitionStatus()</code> synchron abfragen.\n</li><li>Kanalzustandsänderungen, die sich aus der Limitierung ergeben (Übergang in <code>COMM_NO_COMMUNICATION</code>), meldet der ComM asynchron über <code>BswM_ComM_CurrentModeIndication()</code> an den BswM zurück.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Generierung &amp; Variantenkonfiguration:</strong>\n<ul class=\"fig-list\"><li>Fehlt in der EcuC-Konfiguration <code>ComMWakeupInhibitionEnabled = TRUE</code>, werden die Ports <code>CWxxx</code> und das Interface <code>ComM_ChannelWakeup</code> vom RTE-Generator nicht erzeugt (<code>[SWS_ComM_00742]</code>, <code>[SWS_ComM_01008]</code>).\n</li><li>Fehlt <code>ComMModeLimitationEnabled = TRUE</code>, entfallen die Ports <code>CLxxx</code>, <code>modeLimitation</code> sowie die zugehörigen Interfaces (<code>[SWS_ComM_00741]</code>, <code>[SWS_ComM_00743]</code>).\n</li></ul>\n</li><li><strong>BswM-Aktionskonfiguration:</strong>\n<ul class=\"fig-list\"><li>Im BswM-Modul müssen die Aktionen exakt auf die generierten R-Ports gemappt werden. Ein typischer Konfigurationsfehler ist das Setzen von <code>ComM_LimitECUToNoComMode</code> bei gleichzeitigem Erwarten von Restkommunikation auf Teilnetzwerken (PNCs) – die ECU-Limitierung überschreibt alle lokalen Kanal- und PNC-Freigaben.\n</li></ul>\n</li><li><strong>Fehlercodes &amp; Det:</strong>\n<ul class=\"fig-list\"><li>Aufrufe vor <code>ComM_Init()</code> liefern <code>E_NOT_OK</code> und erzeugen den Det-Fehler <code>COMM_E_UNINIT</code>.\n</li><li>Ein ungültiger Index in <code>NetworkHandleType</code> erzeugt <code>COMM_E_WRONG_PARAMETERS</code>.\n</li></ul>\n</li><li><strong>NvM-Kopplung:</strong>\n<ul class=\"fig-list\"><li>Ist <code>ComMGlobalNvMBlockDescriptor</code> konfiguriert, muss zur Erfassung abgewiesener Vollkommunikations-Anfragen der Inhibit-Counter über <code>ReadInhibitCounter()</code> / <code>ResetInhibitCounter()</code> im Fehlerspeicher- oder Shutdown-Pfad berücksichtigt werden.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-6e4c317f85f67896", "to": "FIG-36028b3d7dedc2ba", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-36028b3d7dedc2ba", "to": "FIG-60baeb1d1e869889", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-60baeb1d1e869889", "to": "FIG-917fa846b1fedadb", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Beschriftung <code>provide ComM_ECUModeLimitation</code></strong>: Die Textzeile <code>provide</code> wurde vertikal nach unten verschoben, sodass sie auf gleicher Höhe mit <code>require</code> liegt; der Bezeichner <code>ComM_ECUModeLimitation</code> wurde darunter neu positioniert.\n</li><li><strong>Diagrammlayout</strong>: Der leere Weißraum am unteren Bildrand wurde entfernt (Bildhöhe von 659 auf 495 Pixel reduziert).\n</li></ul>"}, {"from": "FIG-917fa846b1fedadb", "to": "FIG-7eaca75fb6197b53", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7eaca75fb6197b53", "to": "FIG-f22d9f4acbc7d34a", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Port-Darstellung</strong>: Schwarze Vollquadrate mit abgesetzten Ball-and-Socket-Symbolen durch Port-Kästchen auf den Komponentengrenzen mit integrierten Buchsen- (BswM) bzw. Ball-Symbolen (ComM) ersetzt.\n</li><li><strong>Verbindungslinien</strong>: Dichte gepunktete Verbindungslinien durch gestrichelte Linien (Assembly Connectors) ersetzt.\n</li><li><strong>Beschriftung <code>ComM_ChannelWakeup</code></strong>: Die Präfixe <code>require</code> und <code>provide</code> oberhalb der obersten Ports entfallen; beidseitig wird nur noch <code>ComM_ChannelWakeup</code> geführt.\n</li><li><strong>Auslassungspunkte</strong>: Die Fortsetzungspunkte (<code>...</code>) zwischen den Weck- und Moduslimitierungs-Ports auf der ComM-Seite entfallen.\n</li><li><strong>Komponenten-Hintergrund</strong>: Komponentenblöcke sind hellgrau statt weiß hinterlegt.\n</li><li><strong>Typografie</strong>: Umstellung sämtlicher Beschriftungen von einer Serifenschrift auf eine serifenlose Schrift (Sans-Serif).\n</li></ul>"}]};
